import { useMemo } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from dotPlot ----
/** mulberry32, seeded so the age curves are byte-identical on every reload. */
function createRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const AGE_GROUPS = [
  '<10',
  '10-19',
  '20-29',
  '30-39',
  '40-49',
  '50-59',
  '60-69',
  '70-79',
  '80+'
] as const;

type AgeGroup = (typeof AGE_GROUPS)[number];
type AgeShare = { state: string; age: AgeGroup; share: number };

const AGE_MIDPOINT: Record<AgeGroup, number> = {
  '<10': 5,
  '10-19': 15,
  '20-29': 25,
  '30-39': 35,
  '40-49': 45,
  '50-59': 55,
  '60-69': 65,
  '70-79': 75,
  '80+': 85
};

const STATES = [
  'Utah',
  'Texas',
  'Georgia',
  'North Carolina',
  'Colorado',
  'Washington',
  'Nevada',
  'Virginia',
  'Minnesota',
  'Illinois',
  'Ohio',
  'Michigan',
  'New York',
  'Pennsylvania',
  'Connecticut',
  'Vermont',
  'Florida',
  'Maine'
];

function gaussian(x: number, mean: number, sd: number): number {
  return Math.exp(-0.5 * ((x - mean) / sd) ** 2);
}

/** Each state gets a random median age and spread, so rows read as one smooth hump apiece. */
function createAgeShares(seed: number): AgeShare[] {
  const random = createRandom(seed);
  return STATES.flatMap((state) => {
    const median = 30 + random() * 20;
    const spread = 14 + random() * 10;
    const weights = AGE_GROUPS.map((age) => gaussian(AGE_MIDPOINT[age], median, spread));
    const total = weights.reduce((a, b) => a + b, 0);
    return AGE_GROUPS.map((age, i) => ({ state, age, share: weights[i] / total }));
  });
}

/** Synthetic age-distribution data, not the real American Community Survey figures. */
const statePopulationByAge: AgeShare[] = createAgeShares(20260813);

const MARGIN = { top: 46, right: 16, bottom: 6, left: 116 };
const ROW_HEIGHT = 20;
const AXIS_HEIGHT = 26;
const DOT_RADIUS = 3.5;

const formatPercent = d3.format('.0%');

/** One share per group per row, plus the group ordering the colour scale and legend follow. */
export type Data = {
  ages: readonly string[];
  shares: { state: string; age: string; share: number }[];
};

const DEMO: Data = { ages: AGE_GROUPS, shares: statePopulationByAge };

type Row = { state: string; min: number; max: number; dots: { age: string; share: number }[] };

export default function DotPlot({ data = DEMO, width }: { data?: Data; width: number }) {
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);

  const rows: Row[] = useMemo(() => {
    const byState = d3.group(data.shares, (d) => d.state);
    return d3
      .sort(byState, ([state]) => state)
      .map(([state, values]) => ({
        state,
        min: d3.min(values, (d) => d.share) ?? 0,
        max: d3.max(values, (d) => d.share) ?? 0,
        dots: values.map((d) => ({ age: d.age, share: d.share }))
      }));
  }, [data]);

  const innerHeight = rows.length * ROW_HEIGHT;
  const height = MARGIN.top + innerHeight + MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data.shares, (d) => d.share) ?? 0])
        .rangeRound([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scalePoint<string>()
        .domain(rows.map((d) => d.state))
        .range([0, innerHeight])
        .padding(0.5),
    [rows, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(data.ages).range(d3.schemeSpectral[data.ages.length]),
    [data]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        .ticks(Math.max(2, Math.round(innerWidth / 90)))
        .map((v) => ({ value: formatPercent(v), offset: x(v) })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  const legendSlot = innerWidth / data.ages.length;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Dot plot of population share by age group across 18 US states, one row per state with a dot per age bracket connecting the youngest to the oldest share. Synthetic data, not the real American Community Survey figures."
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {xTicks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={-AXIS_HEIGHT} width={innerWidth} />

        {legendSlot >= 44 && (
          <g fontSize={10} transform="translate(0,-40)">
            {data.ages.map((age, i) => (
              <g key={age} transform={`translate(${i * legendSlot},0)`}>
                <rect y={-8} width={10} height={10} fill={color(age)} />
                <text x={14} dy="0.32em" fill="var(--text)">
                  {age}
                </text>
              </g>
            ))}
          </g>
        )}

        {rows.map((row, i) => (
          <g key={row.state} transform={`translate(0,${y(row.state) ?? 0})`}>
            <line x1={x(row.min)} x2={x(row.max)} stroke="var(--line)" />
            <text x={x(row.min) - 8} dy="0.32em" textAnchor="end" fill="var(--text)" fontSize={11}>
              {row.state}
            </text>
            {row.dots.map((d) => (
              <motion.circle
                key={d.age}
                cy={0}
                r={DOT_RADIUS}
                fill={color(d.age)}
                initial={{ cx: x(row.min), opacity: 0 }}
                animate={{ cx: x(d.share), opacity: 1 }}
                transition={{ duration: 0.4, delay: i * 0.02 }}
              />
            ))}
          </g>
        ))}
      </g>
    </svg>
  );
}
